Q: Finding the max value in a map A: <p><a href="https://en.cppreference.com/cpp/container/map" rel="nofollow noreferrer">std::map</a> keeps its elements ordered, so all you need to do is <a href="https://godbolt.org/z/nKEnGEsKn" rel="nofollow noreferrer">grab the last element:</a></p>
<pre><code>#include &lt;map&gt;
#include &lt;print&gt;

int main()
{
    std::map&lt;int, int&gt; m = {{1, 10}, {5, 50}, {3, 30}};
    auto it{m.rbegin()}; 
    std::println(&quot;Max Key: {}&quot;, it-&gt;first);  // Output: 5
    std::println(&quot;Max Value: {}&quot;, it-&gt;second); // Output: 50
}
</code></pre>

Q: Read zip in zip for updating A: <p>I think it's easier this way (using ZipFile)</p>
<pre><code>
try (ZipFile zfParent = new ZipFile(&quot;root.zip&quot;);
     ZipOutputStream outputStream = new ZipOutputStream( Files.newOutputStream(Paths.get(&quot;output.zip&quot;)) )
) {

    Enumeration&lt;? extends ZipEntry&gt; entries = zfParent.entries();

    while (entries.hasMoreElements()) {
        ZipEntry zfChild= entries.nextElement();

        if (zfChild.getName().endsWith(&quot;.zip&quot;)) {
            processNestedZip(zfParent, zfChild, outputStream);
        } else { 
            copyEntry(zfParent, zfChild, outputStream);
        }
    }

}
</code></pre>
<p>Processing the attached ZIP</p>
<pre><code>void processNestedZip(ZipFile zfParent, ZipEntry zfChild, ZipOutputStream outputStream) throws IOException {

    try (InputStream input = zfParent.getInputStream(zfChild);
         ZipInputStream nestedZipStream = new ZipInputStream(input);
         ZipOutputStream nestedOutput = new ZipOutputStream(outputStream)
    ) {

        ZipEntry newZfChild = new ZipEntry(zfChild.getName());
        nestedOutput.putNextEntry(newZfChild);

        ZipEntry nestedZfChild;
        while ((nestedZfChild = nestedZipStream.getNextEntry()) != null) {

            if (nestedZfChild.getName().equals(&quot;file_to_replace.txt&quot;)) {
                replaceFile(nestedOutput, &quot;test.txt&quot;, nestedZfChild);
            } else {                
                copyEntry(nestedZipStream, nestedZfChild, nestedOutput);
            }
        }
    }
}
</code></pre>
<p>Copying the remaining files without modification</p>
<pre><code>void copyEntry(InputStream zfParent, ZipEntry zfChild, ZipOutputStream output) throws IOException {
    output.putNextEntry(new ZipEntry(zfChild.getName()));

    byte[] buffer = new byte[1024];
    int length;

    while ((length = zfParent.read(buffer)) &gt; 0) {
        output.write(buffer, 0, length);
    }

    output.closeEntry();
}
</code></pre>
<p>Replacing the file with a new one</p>
<pre><code>void replaceFile(ZipOutputStream output, String newFile, ZipEntry entry) throws IOException {
    try (InputStream newFileInput = Files.newInputStream(Paths.get(newFile))) {
        output.putNextEntry(new ZipEntry(entry.getName()));

        byte[] buffer = new byte[1024];
        int length;

        while ((length = newFileInput.read(buffer)) &gt; 0) {
            output.write(buffer, 0, length);
        }

        output.closeEntry();
    }
}
</code></pre>
